(()=>{
const C=window.TIVIONE_CONFIG.contact,wa=m=>'https://wa.me/'+C.whatsapp+'?text='+encodeURIComponent(m),path=location.pathname.replace(/^\/+|\/+$/g,'')||'home';
const routes=[['home','Home'],['pricing','Pricing'],['reseller','Reseller'],['apps','Apps'],['guides','Guides'],['tutorials','Tutorials'],['panel','Panel'],['blog','Blog'],['contact','Contact']];
const link=k=>k==='home'?'/':'/'+k+'/';
const features=['Instant activation','22,000+ live channels','88,000+ VOD & series','Global EPG','Premium anti-freeze servers','24/7 support'];
const planData=[['1 Month','€19'],['3 Months','€29'],['6 Months','€39'],['12 Months','€65'],['24 Months','€99']];
const pageHead=(k,t,d)=>`<section class="page-hero"><div class="site-wrap"><div class="kicker">${k}</div><h1>${t}</h1><p class="lead">${d}</p></div></section>`;
const button=(label,msg,variant='')=>`<a class="btn ${variant}" href="${wa(msg)}" target="_blank" rel="noopener">${label} ↗</a>`;
const plans=()=>`<section><div class="site-wrap"><div class="heading"><div class="kicker">Clear pricing</div><h2>One stable service.<br>Five simple durations.</h2><p>Every Tivione plan includes the same high-quality server features and setup help.</p></div><div class="grid five">${planData.map(([name,price],i)=>`<article class="card plan ${i===4?'hot':''}">${i===4?'<span class="tag">Best value</span>':''}<h3>${name}</h3><div class="price">${price}</div><ul class="ticks">${features.slice(0,4).map(x=>'<li>'+x+'</li>').join('')}</ul>${button('Choose '+name,'Hello Tivione, I would like the '+name+' subscription.')}</article>`).join('')}</div></div></section>`;
const workflow=(reseller=false)=>`<section><div class="site-wrap split"><div><div class="kicker">${reseller?'Tivione reseller':'Simple from day one'}</div><h2>${reseller?'One workflow. More control.':'Ready for the screen you use.'}</h2><p class="lead">${reseller?'Create accounts, manage credits and grow with reliable Tivione infrastructure and a responsive team.':'Choose your duration, install a compatible player and ask our team for help whenever you need it.'}</p>${button(reseller?'Talk to reseller support':'Talk to support',reseller?'Hello Tivione, I want details about the reseller panel.':'Hello Tivione, I need help choosing a plan.')}</div><div class="grid">${(reseller?['Sub-reseller access','Xtream / MAG / M3U tools','24/7 panel support']:['Choose a plan','Install a player','Start watching']).map((x,i)=>`<article class="card"><span class="num">0${i+1}</span><h3>${x}</h3><p>${reseller?'Built to keep your customer workflow clear and manageable.':'A straightforward path with help available for each step.'}</p></article>`).join('')}</div></div></section>`;
const home=()=>`<main><section class="hero"><div class="site-wrap"><div class="kicker">Tivione IPTV</div><h1>Entertainment<br>that keeps moving.</h1><p class="lead">A smart, stable IPTV experience with global delivery, clear plans, compatible players and human support.</p><div class="actions"><a class="btn" href="/pricing/">Explore plans</a><a class="btn ghost" href="/reseller/">Explore reseller</a></div><div class="stats"><div class="stat"><b>22K+</b><span>Live channels</span></div><div class="stat"><b>88K+</b><span>VOD & series</span></div><div class="stat"><b>24/7</b><span>Team support</span></div><div class="stat"><b>6</b><span>Player options</span></div></div></div></section><section><div class="site-wrap"><div class="heading"><div class="kicker">Built around you</div><h2>Everything you need.<br>Nothing you do not.</h2></div><div class="grid three">${[['Plans','Choose from 1 to 24 months with transparent pricing.','/pricing/'],['Apps','Find player codes and direct-download guidance.','/apps/'],['Guides','Set up Smart TV, Fire TV, Android and more.','/guides/']].map((x,i)=>`<a class="card" href="${x[2]}"><div class="icon">0${i+1}</div><h3>${x[0]}</h3><p>${x[1]}</p></a>`).join('')}</div></div></section>${plans()}${workflow(true)}<section><div class="site-wrap band"><div><div class="kicker">Need help?</div><h2>Talk to a real Tivione specialist.</h2><p>For subscriptions, player setup and reseller opportunities, contact the team directly.</p></div>${button('Contact on WhatsApp','Hello Tivione, I need assistance.')}</div></section></main>`;
const pricing=()=>`<main>${pageHead('Subscriptions','Choose your Tivione plan.','Straightforward pricing for the duration that suits your viewing.')}${plans()}${workflow(false)}${faq()}</main>`;
const reseller=()=>`<main>${pageHead('Tivione reseller','Build an IPTV business with clarity.','Flexible credits, dependable infrastructure, helpful tools and support when you need it.')}<section><div class="site-wrap grid five">${[['10 Credits','€190'],['20 Credits','Contact sales'],['50 Credits','Contact sales'],['100 Credits','Contact sales'],['Grow','Contact sales']].map(([n,p],i)=>`<article class="card plan ${i===0?'hot':''}"><h3>${n}</h3><div class="price">${p}</div><ul class="ticks"><li>Instant activation</li><li>22,000+ channels</li><li>88,000+ VOD & series</li><li>API access</li><li>Own domain options</li></ul>${button('Request package','Hello Tivione, I am interested in the '+n+' reseller package.')}</article>`).join('')}</div></section><section><div class="site-wrap"><div class="heading"><div class="kicker">Credit rules</div><h2>Flexible terms for every customer.</h2></div><div class="grid three">${['0.1 credit = 1 month','0.3 credit = 3 months','0.5 credit = 6 months','1 credit = 12 months','24/7 dedicated support','White-label / own domain'].map(x=>`<article class="card"><h3>${x}</h3><p>Clear credit options designed for a practical Tivione reseller workflow.</p></article>`).join('')}</div></div></section>${workflow(true)}${faq()}</main>`;
const apps=()=>`<main>${pageHead('Player library','Choose the player that fits your device.','Use the listed code or download link, then follow the device guide to complete your setup.')}<section><div class="site-wrap grid three">${[['IBO Player Pro','Downloader code: 2701638','aftv.news/2701638'],['Smart STB','Downloader code: 8796547','aftv.news/8796547'],['IPTV Smarters','Downloader code: 5926554','http://tivi-center.net/app/apk/TiviOne-Smart.apk'],['TiviMate','Downloader code: 8208106','http://tivi-center.net/app/apk/TIVIMATE.apk'],['Wave','Downloader code: 1087596','http://tivi-center.net/app/apk/TIVI-MATE-Wave.apk'],['Purple Player','Downloader code: 7067392','http://tivi-center.net/app/apk/TIVI-ONEpur.apk']].map(([n,c,u])=>`<article class="card"><div class="icon">▶</div><h3>${n}</h3><p class="appcode">${c}</p><a class="btn ghost" href="${u}" target="_blank" rel="noopener">Open resource ↗</a></article>`).join('')}</div></section>${workflow(false)}</main>`;
const guides=()=>`<main>${pageHead('Device guides','Set up on the screen you own.','Simple, device-first guidance for your preferred IPTV player.')}<section><div class="site-wrap grid three">${['Fire TV & Firestick','Smart TV','Android TV & mobile','iPhone & iPad','Windows & macOS','MAG & Enigma2'].map((x,i)=>`<article class="card"><span class="num">GUIDE 0${i+1}</span><h3>${x}</h3><p>Install a compatible player, select the recommended login method and enter the details received after activation.</p><a href="/tutorials/">View tutorials →</a></article>`).join('')}</div></section>${faq()}</main>`;
const tutorials=()=>`<main>${pageHead('Tutorials','Learn at your own pace.','Short practical walkthroughs for planning, installation and everyday player use.')}<section><div class="site-wrap grid three">${['How to choose an IPTV plan','Install a player on Fire TV','Connect with Xtream Codes','Use M3U on a compatible player','Improve home streaming stability','Read your global EPG'].map((x,i)=>`<article class="card"><span class="num">TUTORIAL ${i+1}</span><h3>${x}</h3><p>Start with a supported device, keep your app updated and contact Tivione if you need help with a specific step.</p><a href="/contact/">Ask for help →</a></article>`).join('')}</div></section></main>`;
const panel=()=>`<main>${pageHead('Tivione panel','Tools for organised reseller work.','Discuss reseller access, credits, available formats and custom-domain options with the team.')}<section><div class="site-wrap grid three flow">${['Create & renew lines','Manage credits','Support customers'].map(x=>`<article class="card"><h3>${x}</h3><p>Use a clear workflow designed around account actions, subscription durations and customer support.</p></article>`).join('')}</div></section>${workflow(true)}</main>`;
const blog=()=>`<main>${pageHead('Tivione journal','Helpful reads for smarter streaming.','Setup notes, player choices and practical IPTV learning resources.')}<section><div class="site-wrap grid three">${['IPTV setup checklist for beginners','Which player works for my device?','TiviMate: the first connection','How global EPG works','Home network tips for streaming','Starting a reseller workflow'].map((x,i)=>`<article class="card"><span class="num">ARTICLE ${String(i+1).padStart(2,'0')}</span><h3>${x}</h3><p>Useful advice to help you make an informed choice and prepare your viewing setup.</p><a href="/tutorials/">Read tutorial →</a></article>`).join('')}</div></section></main>`;
const faq=()=>`<section><div class="site-wrap split"><div><div class="kicker">Answers first</div><h2>A few things worth knowing.</h2><p class="lead">Clear answers before you choose a plan or set up your player.</p></div><div class="faq">${[['How quickly is activation completed?','Contact the team after your order. They will confirm the activation and next setup steps.'],['Can I use more than one device?','Device and connection use should be confirmed with the team for your selected plan.'],['Which player should I install?','Choose a player from the Apps page based on the device you use.'],['Can resellers use their own domain?','Ask the reseller team about available white-label and own-domain options.']].map(x=>`<details><summary>${x[0]}</summary><p>${x[1]}</p></details>`).join('')}</div></div></section>`;
const contact=()=>`<main>${pageHead('Tivione support','Let us point you in the right direction.','Choose the contact channel that works best for subscriptions, player setup or reseller enquiries.')}<section><div class="site-wrap grid three"><a class="card" href="${wa('Hello Tivione, I need support.')}" target="_blank"><div class="icon">W</div><h3>WhatsApp</h3><p>Fastest route for orders, questions and setup help.</p></a><a class="card" href="https://t.me/${C.telegram}" target="_blank"><div class="icon">T</div><h3>Telegram</h3><p>@${C.telegram}</p></a><a class="card" href="mailto:${C.email}"><div class="icon">@</div><h3>Email</h3><p>${C.email}</p></a></div></section></main>`;
const legal=(title,text)=>`<main>${pageHead('Tivione information',title,text)}<section><article class="site-wrap article"><h2>${title}</h2><p>${text}</p><p>Tivione uses the information you provide through its support channels only to respond to requests and provide assistance. Contact the team if you have questions about plans, player setup, account access or policy information.</p><p>Service availability, device compatibility and setup requirements can vary. Please confirm your intended device and player before activation.</p><p>For any notice or policy enquiry, email <a href="mailto:${C.email}">${C.email}</a>.</p></article></section></main>`;
const pages={home,pricing,reseller,apps,guides,tutorials,panel,blog,contact,about:()=>legal('About Tivione','Tivione brings plans, player information and professional reseller tools together in one clear experience.'),privacy:()=>legal('Privacy policy','Read how Tivione handles support communications and visitor information.'),dmca:()=>legal('DMCA policy','Tivione respects intellectual-property rights and reviews properly submitted copyright notices.'),refund:()=>legal('Refund policy','Contact support promptly if you experience a service or setup issue so the team can review the details.'),terms:()=>legal('Terms of service','Review the general conditions that apply to use of Tivione support and service information.')};
const header=()=>`<header class="nav"><div class="site-wrap navin"><a class="logo" href="/"><img src="/assets/tivione.webp" alt="Tivione IPTV"><span>Tivione <em>IPTV</em></span></a><button class="menu" aria-label="Open navigation">☰</button><nav class="links">${routes.map(([k,n])=>`<a class="${path===k?'active':''}" href="${link(k)}">${n}</a>`).join('')}</nav><a class="nav-cta" href="/pricing/">Get started</a></div></header>`;
const footer=()=>`<footer class="footer"><div class="site-wrap footergrid"><div><a class="logo" href="/"><img src="/assets/tivione.webp" alt="Tivione IPTV"><span>Tivione <em>IPTV</em></span></a><p>Smart IPTV plans, player guidance and reseller tools built around clarity.</p></div><div><strong>Explore</strong>${routes.slice(1).map(([k,n])=>`<a href="${link(k)}">${n}</a>`).join('')}</div><div><strong>Information</strong><a href="/about/">About</a><a href="/privacy/">Privacy</a><a href="/dmca/">DMCA</a><a href="/refund/">Refund</a><a href="/terms/">Terms</a></div></div><div class="site-wrap"><small>© 2026 Tivione IPTV. All rights reserved.</small></div></footer>`;
document.title=(path==='home'?'Tivione IPTV':(path[0].toUpperCase()+path.slice(1))+' | Tivione IPTV');document.getElementById('app').innerHTML=header()+(pages[path]||pages.home)()+footer();document.querySelector('.menu').onclick=()=>document.querySelector('.links').classList.toggle('open');
})();
